        java: "import java.io.*;\nimport java.util.*;\nimport com.google.gson.*;\n\npublic class Main {\n    static Object solve(JsonObject data) {\n        JsonArray tempsA = data.has(\"temperatures\") && data.get(\"temperatures\").isJsonArray()\n            ? data.getAsJsonArray(\"temperatures\") : new JsonArray();\n        int n = tempsA.size();\n        int[] ans = new int[n];\n        Deque<Integer> st = new ArrayDeque<>();\n        for (int i = 0; i < n; i++) {\n            int t = tempsA.get(i).getAsInt();\n            while (!st.isEmpty() && tempsA.get(st.peek()).getAsInt() < t) {\n                int j = st.pop();\n                ans[j] = i - j;\n            }\n            st.push(i);\n        }\n        return ans;\n    }\n\n    public static void main(String[] args) throws Exception {\n        JsonObject data = JsonParser.parseString(new String(System.in.readAllBytes())).getAsJsonObject();\n        Object result = solve(data);\n        System.out.println(new Gson().toJson(result));\n    }\n}\n",
