    "evaluate-reverse-polish-notation": {
        java: "import java.io.*;\nimport java.util.*;\nimport com.google.gson.*;\n\npublic class Main {\n    static Object solve(JsonObject data) {\n        JsonArray tokensA = data.has(\"tokens\") && data.get(\"tokens\").isJsonArray()\n            ? data.getAsJsonArray(\"tokens\") : new JsonArray();\n        Deque<Integer> st = new ArrayDeque<>();\n        for (JsonElement el : tokensA) {\n            String tok = el.getAsString();\n            if (\"+-*/\".contains(tok)) {\n                int b = st.pop(), a = st.pop();\n                if (tok.equals(\"+\")) st.push(a + b);\n                else if (tok.equals(\"-\")) st.push(a - b);\n                else if (tok.equals(\"*\")) st.push(a * b);\n                else st.push(a / b);\n            } else {\n                st.push(Integer.parseInt(tok));\n            }\n        }\n        return st.pop();\n    }\n\n    public static void main(String[] args) throws Exception {\n        JsonObject data = JsonParser.parseString(new String(System.in.readAllBytes())).getAsJsonObject();\n        Object result = solve(data);\n        System.out.println(new Gson().toJson(result));\n    }\n}\n",
        cpp: "#include <iostream>\n#include <string>\n#include <vector>\n#include <unordered_map>\n#include <unordered_set>\n#include <map>\n#include <set>\n#include <queue>\n#include <stack>\n#include <algorithm>\n#include <climits>\n#include \"json.hpp\"\nusing json = nlohmann::json;\n\njson solve(const json& data) {\n    std::vector<std::string> tokens = data.value(\"tokens\", std::vector<std::string>{});\n    std::vector<int> st;\n    for (const std::string& tok : tokens) {\n        if (tok == \"+\" || tok == \"-\" || tok == \"*\" || tok == \"/\") {\n            int b = st.back(); st.pop_back();\n            int a = st.back(); st.pop_back();\n            if (tok == \"+\") st.push_back(a + b);\n            else if (tok == \"-\") st.push_back(a - b);\n            else if (tok == \"*\") st.push_back(a * b);\n            else st.push_back(a / b);\n        } else {\n            st.push_back(std::stoi(tok));\n        }\n    }\n    return st.back();\n}\n\nint main() {\n    json data;\n    std::cin >> data;\n    json result = solve(data);\n    std::cout << result.dump();\n    return 0;\n}\n",
    },
    "binary-tree-level-order-traversal": {
        java: "import java.io.*;\nimport java.util.*;\nimport com.google.gson.*;\n\npublic class Main {\n    static Object solve(JsonObject data) {\n        class TNode {\n            int val;\n            TNode left, right;\n            TNode(int v) { val = v; }\n        }\n        TNode buildTree(JsonArray arr) {\n            if (arr == null || arr.size() == 0 || arr.get(0).isJsonNull()) return null;\n            List<TNode> nodes = new ArrayList<>();\n            for (JsonElement el : arr) {\n                nodes.add(el.isJsonNull() ? null : new TNode(el.getAsInt()));\n            }\n            for (int i = 0; i < nodes.size(); i++) {\n                TNode node = nodes.get(i);\n                if (node == null) continue;\n                int l = 2 * i + 1, r = 2 * i + 2;\n                if (l < nodes.size()) node.left = nodes.get(l);\n                if (r < nodes.size()) node.right = nodes.get(r);\n            }\n            return nodes.get(0);\n        }\n        \n        JsonArray rootA = data.has(\"root\") && data.get(\"root\").isJsonArray()\n            ? data.getAsJsonArray(\"root\") : new JsonArray();\n        TNode root = buildTree(rootA);\n        if (root == null) return new ArrayList<>();\n        List<List<Integer>> ans = new ArrayList<>();\n        Deque<TNode> q = new ArrayDeque<>();\n        q.add(root);\n        while (!q.isEmpty()) {\n            int size = q.size();\n            List<Integer> level = new ArrayList<>();\n            for (int i = 0; i < size; i++) {\n                TNode node = q.removeFirst();\n                level.add(node.val);\n                if (node.left != null) q.add(node.left);\n                if (node.right != null) q.add(node.right);\n            }\n            ans.add(level);\n        }\n        return ans;\n    }\n\n    public static void main(String[] args) throws Exception {\n        JsonObject data = JsonParser.parseString(new String(System.in.readAllBytes())).getAsJsonObject();\n        Object result = solve(data);\n        System.out.println(new Gson().toJson(result));\n    }\n}\n",
        cpp: "#include <iostream>\n#include <string>\n#include <vector>\n#include <unordered_map>\n#include <unordered_set>\n#include <map>\n#include <set>\n#include <queue>\n#include <stack>\n#include <algorithm>\n#include <climits>\n#include \"json.hpp\"\nusing json = nlohmann::json;\n\njson solve(const json& data) {\n    struct TNode {\n        int val;\n        TNode *left, *right;\n        explicit TNode(int v) : val(v), left(nullptr), right(nullptr) {}\n    };\n    TNode* buildTree(const json& arr) {\n        if (!arr.is_array() || arr.empty() || arr[0].is_null()) return nullptr;\n        std::vector<TNode*> nodes;\n        nodes.reserve(arr.size());\n        for (const auto& el : arr) {\n            nodes.push_back(el.is_null() ? nullptr : new TNode(el.get<int>()));\n        }\n        for (size_t i = 0; i < nodes.size(); ++i) {\n            if (!nodes[i]) continue;\n            size_t l = 2 * i + 1, r = 2 * i + 2;\n            if (l < nodes.size()) nodes[i]->left = nodes[l];\n            if (r < nodes.size()) nodes[i]->right = nodes[r];\n        }\n        return nodes[0];\n    }\n    \n    json rootA = data.contains(\"root\") ? data[\"root\"] : json::array();\n    TNode* root = buildTree(rootA);\n    if (!root) return json::array();\n    json ans = json::array();\n    std::deque<TNode*> q = {root};\n    while (!q.empty()) {\n        int size = (int)q.size();\n        json level = json::array();\n        for (int i = 0; i < size; ++i) {\n            TNode* node = q.front();\n            q.pop_front();\n            level.push_back(node->val);\n            if (node->left) q.push_back(node->left);\n            if (node->right) q.push_back(node->right);\n        }\n        ans.push_back(level);\n    }\n    return ans;\n}\n\nint main() {\n    json data;\n    std::cin >> data;\n    json result = solve(data);\n    std::cout << result.dump();\n    return 0;\n}\n",
    },
