        java: "import java.io.*;\nimport java.util.*;\nimport com.google.gson.*;\n\npublic class Main {\n    static Object solve(JsonObject data) {\n        String s = data.get(\"s\").getAsString();\n        int n = s.length();\n        String best = \"\";\n        for (int center = 0; center < 2 * n - 1; center++) {\n            int lo = center / 2, hi = lo + center % 2;\n            while (lo >= 0 && hi < n && s.charAt(lo) == s.charAt(hi)) {\n                if (hi - lo + 1 > best.length()) best = s.substring(lo, hi + 1);\n                lo--;\n                hi++;\n            }\n        }\n        return best;\n    }\n\n    public static void main(String[] args) throws Exception {\n        JsonObject data = JsonParser.parseString(new String(System.in.readAllBytes())).getAsJsonObject();\n        Object result = solve(data);\n        System.out.println(new Gson().toJson(result));\n    }\n}\n",
